    <?php foreach(['es'=>'Español','en'=>'English','pt-BR'=>'Português (Brasil)'] as $locale=>$label):$tr=$place['translations'][$locale]??[];?><label class="wide"><?=esc($label)?> · Enlace al operador (opcional)<input type="url" name="places[<?=$i?>][translations][<?=esc($locale)?>][external_url]" value="<?=esc($tr['external_url']??'')?>" placeholder="https://..."></label><label><?=esc($label)?> · Texto del enlace<input name="places[<?=$i?>][translations][<?=esc($locale)?>][external_label]" maxlength="180" value="<?=esc($tr['external_label']??'')?>" placeholder="Consultar con el operador"></label><?php endforeach ?>
    <label>Origen de la imagen<select name="places[<?=$i?>][image_origin]"><option value="ai_generated" <?=($place['image_origin']??'')==='ai_generated'?'selected':''?>>Generada con IA</option><option value="own" <?=($place['image_origin']??'')==='own'?'selected':''?>>Propia o cedida</option><option value="external" <?=!isset($place['image_origin'])||$place['image_origin']==='external'?'selected':''?>>Externa (requiere crédito y licencia)</option></select></label><label>Autor o crédito<input name="places[<?=$i?>][image_creator]" maxlength="255" value="<?=esc($place['image_creator']??'')?>"></label><label>Licencia o nota de uso<input name="places[<?=$i?>][image_license]" maxlength="100" placeholder="Ej. CC BY-SA 4.0" value="<?=esc($place['image_license']??'')?>"></label><label class="wide">Página original de la imagen (si aplica)<input type="url" name="places[<?=$i?>][image_source_url]" placeholder="https://..." value="<?=esc($place['image_source_url']??'')?>"></label><label class="wide">Enlace de la licencia (obligatorio si es externa)<input type="url" name="places[<?=$i?>][image_license_url]" placeholder="https://creativecommons.org/..." value="<?=esc($place['image_license_url']??'')?>"></label>
    <?php foreach(['es'=>'Español','en'=>'English','pt-BR'=>'Português (Brasil)'] as $locale=>$label):?><label><?=esc($label)?> · Texto alternativo<input name="places[<?=$i?>][image_alt][<?=esc($locale)?>]" maxlength="500" value="<?=esc($place['image_alt'][$locale]??'')?>"></label><label><?=esc($label)?> · Leyenda<input name="places[<?=$i?>][image_caption][<?=esc($locale)?>]" maxlength="500" value="<?=esc($place['image_caption'][$locale]??'')?>"></label><?php endforeach ?>
    </div></details></div></details><?php
}
